package org.deeptimeline.app
import android.content.ContentValues
import android.content.Context
import android.database.sqlite.SQLiteDatabase
import android.database.sqlite.SQLiteOpenHelper
import java.time.LocalDateTime
import java.time.format.DateTimeFormatter
class EventStore(context:Context):SQLiteOpenHelper(context,"deep_timeline.db",null,3){override fun onCreate(db:SQLiteDatabase){db.execSQL("CREATE TABLE events(id TEXT PRIMARY KEY,title TEXT NOT NULL,sec INTEGER NOT NULL,nano INTEGER NOT NULL,civil TEXT NOT NULL,mode TEXT NOT NULL,coords TEXT NOT NULL,zone TEXT NOT NULL,offset_nano TEXT NOT NULL,created INTEGER NOT NULL,updated INTEGER NOT NULL,max_span_amount TEXT NOT NULL DEFAULT '',max_span_unit TEXT NOT NULL DEFAULT 'DAY')");db.execSQL("CREATE INDEX events_time ON events(sec,nano,id)")};override fun onUpgrade(db:SQLiteDatabase,oldVersion:Int,newVersion:Int){if(oldVersion<2){val changed=ArrayList<Pair<String,String>>();db.rawQuery("SELECT id,civil FROM events",null).use{c->while(c.moveToNext()){val parsed=runCatching{LocalDateTime.parse(c.getString(1),DateTimeFormatter.ISO_LOCAL_DATE_TIME)}.getOrNull();if(parsed!=null&&parsed.year<=0)changed.add(Pair(c.getString(0),TimeMath.formatCivil(parsed)))}};for((id,civil) in changed){val values=ContentValues();values.put("civil",civil);db.update("events",values,"id=?",arrayOf(id))}};if(oldVersion<3){db.execSQL("ALTER TABLE events ADD COLUMN max_span_amount TEXT NOT NULL DEFAULT ''");db.execSQL("ALTER TABLE events ADD COLUMN max_span_unit TEXT NOT NULL DEFAULT 'DAY'")}};fun all():List<TimelineEvent>{val result=ArrayList<TimelineEvent>();readableDatabase.rawQuery("SELECT id,title,sec,nano,civil,mode,coords,zone,offset_nano,created,updated,max_span_amount,max_span_unit FROM events ORDER BY sec,nano,id",null).use{c->while(c.moveToNext())result.add(TimelineEvent(c.getString(0),c.getString(1),Moment(c.getLong(2),c.getInt(3)),c.getString(4),c.getString(5),c.getString(6),c.getString(7),c.getString(8),c.getLong(9),c.getLong(10),c.getString(11),c.getString(12)))};return result};fun save(event:TimelineEvent){val v=ContentValues();v.put("id",event.id);v.put("title",event.title);v.put("sec",event.moment.second);v.put("nano",event.moment.nano);v.put("civil",event.civil);v.put("mode",event.mode);v.put("coords",event.coords);v.put("zone",event.zone);v.put("offset_nano",event.offsetNano);v.put("created",event.created);v.put("updated",event.updated);v.put("max_span_amount",event.maxScaleAmount);v.put("max_span_unit",event.maxScaleUnit);writableDatabase.beginTransaction();try{writableDatabase.insertWithOnConflict("events",null,v,SQLiteDatabase.CONFLICT_REPLACE);writableDatabase.setTransactionSuccessful()}finally{writableDatabase.endTransaction()}};fun delete(id:String){writableDatabase.beginTransaction();try{writableDatabase.delete("events","id=?",arrayOf(id));writableDatabase.setTransactionSuccessful()}finally{writableDatabase.endTransaction()}}fun saveBatch(events:List<TimelineEvent>){writeBatch(events,false)};fun replaceAll(events:List<TimelineEvent>){require(events.isNotEmpty()){"Select at least one event for overwrite"};require(events.map{it.id}.toSet().size==events.size){"Duplicate UUIDs in overwrite selection"};writeBatch(events,true)};private fun writeBatch(events:List<TimelineEvent>,replace:Boolean){val db=writableDatabase;db.beginTransaction();try{if(replace)db.delete("events",null,null);val v=ContentValues();for(event in events){v.clear();v.put("id",event.id);v.put("title",event.title);v.put("sec",event.moment.second);v.put("nano",event.moment.nano);v.put("civil",event.civil);v.put("mode",event.mode);v.put("coords",event.coords);v.put("zone",event.zone);v.put("offset_nano",event.offsetNano);v.put("created",event.created);v.put("updated",event.updated);v.put("max_span_amount",event.maxScaleAmount);v.put("max_span_unit",event.maxScaleUnit);require(db.insertWithOnConflict("events",null,v,SQLiteDatabase.CONFLICT_REPLACE)!=-1L){"Failed to write ${event.title}"}};db.setTransactionSuccessful()}finally{db.endTransaction()}}}
